-- Study Abroad country content, BATCH 26: Gambia, Sierra Leone, Liberia, Malawi, Lesotho, Eswatini, Seychelles, South Sudan, Sudan.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('gambia', 'sierra-leone', 'liberia', 'malawi', 'lesotho', 'eswatini', 'seychelles', 'south-sudan', 'sudan'));
UPDATE countries SET why_title = 'Why study in the Gambia?', why_body = '<p>The Gambia offers English-medium degrees at the University of The Gambia and a few private institutions in a small, peaceful West African country.<ul><li>English-medium teaching</li><li>Small, welcoming country</li><li>Strengths in agriculture, education and health</li><li>Low living costs</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Visa rules depend on nationality; ECOWAS citizens can enter free. Students often obtain a <strong>student pass</strong> at the immigration office on arrival with an acceptance letter, and visas are regulated by the Gambia Immigration Department.</p><ul><li>Letter of acceptance from the university</li><li>Student pass from immigration (secondary guide)</li><li>Students generally cannot work on a student permit; working needs a residence and work permit</li><li>AIU lists student-visa guidance on its site</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Gambia Immigration Department and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each institution; one guide noted that the UTG portal showed no admission round open on 18 October 2026.</p><ul><li>Academic transcripts and certificates, legalised</li><li>English proof for English-medium programmes</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>UTG does not publish its tuition online; admission letters give payment details.</p><ul><li>Ask UTG for fees in writing</li><li>Living costs: about US$250-$450 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'gambia';
UPDATE countries SET why_title = 'Why study in Sierra Leone?', why_body = '<p>Sierra Leone is home to Fourah Bay College, the oldest university in West Africa (founded in 1827), with English-medium degrees in humanities, engineering and sciences.<ul><li>English-medium teaching</li><li>Fourah Bay College (founded 1827)</li><li>Strengths in arts, mining and agriculture</li><li>Low living costs</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>A third-party guide says a <strong>student visa</strong> is needed and should be applied for at a Sierra Leone embassy or consulate after acceptance; official online information is limited.</p><ul><li>Admission letter from the university</li><li>Student visa from an embassy or consulate</li><li>Confirm requirements with the embassy or university international office</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Sierra Leone embassy and the University of Sierra Leone site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each institution.</p><ul><li>Academic transcripts and certificates, legalised</li><li>English proof for English-medium programmes</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No official fee schedule was found.</p><ul><li>One programme page (TEA-LP) lists US$8,000 for international students; likely not general tuition</li><li>Ask the registry for fees</li><li>Living costs: about US$250-$450 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'sierra-leone';
UPDATE countries SET why_title = 'Why study in Liberia?', why_body = '<p>Liberia offers English-medium degrees at the University of Liberia and other institutions at low cost, though information for international students is limited.<ul><li>English-medium teaching</li><li>University of Liberia, Cuttington University</li><li>Low living costs</li><li>Strengths in agriculture, health and education</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Liberia does not appear to have a distinct student visa. Admitted students get an admission letter to use for the visa, and a residence permit is needed to stay longer. Visa on arrival is for tourism, business and transit only, not for study.</p><ul><li>Admission letter from a Liberian institution</li><li>Residence permit for longer stays</li><li>Work is restricted; no official rule allows part-time work for students</li><li>Check with the Liberia Immigration Service</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Liberia Immigration Service and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each institution.</p><ul><li>Academic transcripts and certificates, legalised</li><li>English proof for English-medium programmes</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Sources conflict on UL tuition.</p><ul><li>One guide: US$5,000 minimum for international students; another says public university tuition is free with a US$100 registration fee; UL publishes no international rate</li><li>Ask UL admissions in writing</li><li>Living costs: about US$250-$450 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'liberia';
UPDATE countries SET why_title = 'Why study in Malawi?', why_body = '<p>Malawi has public universities such as the University of Malawi, Mzuzu University, LUANAR and Kamuzu University of Health Sciences, teaching in English.<ul><li>English-medium teaching</li><li>Strengths in agriculture, health and education</li><li>Peaceful country</li><li>Lake Malawi</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>A <strong>Student Permit</strong> lets a foreign national enter Malawi to study at an approved institution, filed at Immigration Headquarters or regional offices. A secondary guide says the entry visa allows 30 days, during which the permit is applied for inside Malawi.</p><ul><li>Admission letter and covering letter from the university</li><li>Medical report and police clearance from your home country</li><li>Proof of funds or scholarship letter (no official minimum found; one aggregator says about US$5,000)</li><li>Application form and the applicable fee</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Malawi Department of Immigration and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates, legalised</li><li>English proof for English-medium programmes</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>UNIMA and KUHeS figures are the clearest.</p><ul><li>UNIMA postgraduate and fee-paying programmes: about US$8,000 a year for international (non-SADC) students in 2026/27</li><li>KUHeS undergraduate generic programmes: US$8,722.50 a year, plus US$420 a year medical scheme registration</li><li>Mzuzu and LUANAR: no 2026 international fees found</li><li>Living costs: about US$250-$450 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'malawi';
UPDATE countries SET why_title = 'Why study in Lesotho?', why_body = '<p>Lesotho offers English-medium degrees at the National University of Lesotho and Limkokwing University in a small mountain kingdom surrounded by South Africa.<ul><li>English-medium teaching</li><li>National University of Lesotho</li><li>Limkokwing University of Creative Technology</li><li>Mountain landscape</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Lesotho does not publish one detailed public student-visa manual. Guides list passport copies, previous education certificates, proof of sponsorship, medical report, medical insurance and a return ticket; one college says the permit takes about 8 weeks.</p><ul><li>Admission letter from the institution</li><li>Proof of sponsorship, medical report and medical insurance</li><li>Return ticket</li><li>Confirm with the Ministry of Home Affairs or the nearest Lesotho mission</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Lesotho Ministry of Home Affairs and your institution site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly; the NUL application listing names an online form, IELTS/TOEFL and a passport (confirm for your country).</p><ul><li>Academic transcripts and certificates, legalised</li><li>English proof for English-medium programmes</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>NUL fee figures conflict.</p><ul><li>One listing: about US$530 a year for all students; guide: LSL 15,000-40,000 a year; a news report: M25,000-30,000 a year (undated)</li><li>Tuition is paid before each semester</li><li>Living costs: about US$300-$500 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'lesotho';
UPDATE countries SET why_title = 'Why study in Eswatini?', why_body = '<p>Eswatini offers English-medium degrees at the University of Eswatini and private universities in a small, stable Southern African kingdom.<ul><li>English-medium teaching</li><li>University of Eswatini</li><li>Southern Africa Nazarene University</li><li>Safe, scenic country</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Applicants file for a <strong>student permit</strong> with Home Affairs (aggregators cite Form 10), with school or Ministry of Education support evidence. The permit is usually tied to the course duration; confirm the fee with Home Affairs.</p><ul><li>Admission letter and Ministry of Education support letter</li><li>Application with Home Affairs (Form 10 per aggregators)</li><li>Check whether a short-stay category applies instead</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Eswatini Ministry of Home Affairs and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each institution.</p><ul><li>Academic transcripts and certificates, legalised</li><li>English proof for English-medium programmes</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No official UNESWA fee schedule was found.</p><ul><li>uniRank estimate: US$1,000-$7,499 a year across levels</li><li>Waterford Kamhlaba and other schools publish separate fee schedules</li><li>Living costs: about US$300-$500 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'eswatini';
UPDATE countries SET why_title = 'Why study in Seychelles?', why_body = '<p>Seychelles offers English-medium degrees at the University of Seychelles in an island nation known for tourism, marine science and environment studies.<ul><li>English-medium teaching</li><li>Marine and environmental science</li><li>Tourism and hospitality sector</li><li>Safe island nation</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>International students need a <strong>Student''s Permit</strong> before travel, issued to non-Seychellois students accepted at an approved institution by the Immigration and Civil Status department. It does not allow work.</p><ul><li>Admission letter from an approved institution</li><li>Student Permit issued before travel</li><li>Fee conflicts: UniSey asks for proof of a US$500 permit fee while older government documents list SCR 1,500 valid for the course</li><li>Check with Immigration and Civil Status</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Seychelles Immigration and Civil Status department and UniSey site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to UniSey; no English test score was listed for international applicants, so ask about the language of instruction.</p><ul><li>Academic transcripts and certificates, legalised</li><li>English proof for English-medium programmes</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Figures conflict.</p><ul><li>One guide: local students from about US$875 a year, international from about US$17,500</li><li>Another cites UniSey 2024/25: SCR 165,000 a year for most bachelor''s degrees; a third says no separate international rate is listed</li><li>An international scholarship with tuition reduction may exist; check UniSey</li><li>Living costs: about US$900-$1,500 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'seychelles';
UPDATE countries SET why_title = 'Why study in South Sudan?', why_body = '<p>South Sudan has public universities such as the University of Juba, but security conditions are severe and study is not currently advisable.<ul><li>University of Juba and other public universities</li><li>English-medium teaching</li><li>Limited information for international students</li></ul></p><p>Official governments advise against travel to South Sudan. This page is informational only and does not recommend travel.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>A student visa is required and obtained through the government e-visa portal before departure (Canadian advice). South Sudan''s public-facing visa information is less standardised than most countries; contact the embassy.</p><ul><li>Admission letter from a South Sudanese university</li><li>E-visa portal application before departure</li><li>The UK advises against all travel; the US says Do Not Travel; Canada says avoid all travel</li><li>The UK notes Ebola cases in neighbouring DR Congo and Uganda (May 2026)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official South Sudan embassy and your government''s travel advice site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>No official admission information was found; contact the universities directly.</p><ul><li>Academic transcripts and certificates, legalised</li><li>English proof for English-medium programmes</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No tuition figures were found.</p><ul><li>Contact the universities directly for fees</li><li>Living costs: not estimated because of conditions</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'south-sudan';
UPDATE countries SET why_title = 'Why study in Sudan?', why_body = '<p>Sudan has long-established universities, but the ongoing conflict makes study very difficult and not currently advisable.<ul><li>University of Khartoum and other public universities</li><li>Arabic and English instruction</li><li>Check current conditions before planning</li></ul></p><p>Official governments advise against travel to Sudan. This page is informational only and does not recommend travel.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>A student visa is required; students apply through the Sudanese embassy once admitted and register with the Aliens Department within 3 days of arrival (Canadian advice).</p><ul><li>Admission letter from a Sudanese university</li><li>The UK and Canada advise against all travel (18 October 2026) and the US says Do Not Travel</li><li>Separately, the UK refuses new student visas for Sudanese nationals applying from outside the UK from 26 March 2026</li><li>University of Khartoum Engineering opened 2026-27 registration on 10 October 2026, but timelines conflict in reports</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Sudanese embassy and your government''s travel advice site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>No official admission information was found; contact the universities directly.</p><ul><li>Academic transcripts and certificates, legalised</li><li>English proof for English-medium programmes</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No tuition figures or international scholarships were found.</p><ul><li>Contact the universities directly for fees</li><li>Living costs: not estimated because of conditions</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Arabic or English proof depending on programme</li></ul>' WHERE slug = 'sudan';
COMMIT;
